// ~4 characters per token is a decent English-text estimate
function estimateTokens(text) {
  return Math.ceil(text.length / 4);
}

const prompt = 'List the top 5 skills for a backend engineer.';
console.log(estimateTokens(prompt)); // ~15 input tokens

const generationConfig = {
  temperature: 0.0,   // extraction: repeatable answers
  maxOutputTokens: 200 // hard cap on cost per request
};

export async function askModel(prompt) {
  const res = await fetch(
    'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent',
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': process.env.GEMINI_API_KEY
      },
      body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
      signal: AbortSignal.timeout(15000)
    }
  );
  if (!res.ok) throw new Error(`LLM request failed with status ${res.status}`);
  const data = await res.json();
  return data.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
}

const res = await fetch(endpoint + '?alt=sse', { method: 'POST', headers, body });
const reader = res.body.getReader();
const decoder = new TextDecoder();
let buffer = '';

while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += decoder.decode(value, { stream: true });
  const lines = buffer.split('\n');
  buffer = lines.pop(); // keep the incomplete tail
  for (const line of lines) {
    if (!line.startsWith('data: ')) continue;
    onToken(JSON.parse(line.slice(6)).candidates[0].content.parts[0].text);
  }
}

