async function summarize(jobId, text) {
  const key = `summary:${jobId}`;
  const hit = await redis.get(key);
  if (hit) return { source: 'cache', summary: hit };

  try {
    const summary = await askModel(buildPrompt(text));
    await redis.set(key, summary, { EX: 3600 });
    return { source: 'model', summary };
  } catch (err) {
    logMetric('summary.fallback', { status: err.status });
    return { source: 'fallback', summary: truncate(text, 200) };
  }
}
